{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "조회 병목의 근거를 바탕으로 인덱스 추가 외에 조인 정리까지 적용한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 운영 화면의 신고 목록 조회에 3.2초가 걸렸다.",
          "task": "조회 병목에 맞는 개선 방법을 선택하고 응답 시간을 줄여야 했다.",
          "action": "실행 계획에서 확인한 병목을 근거로 인덱스 추가와 조인 정리를 적용했다.",
          "result": "조회 시간이 3.2초에서 0.4초로 줄어든 것을 측정으로 확인했다."
        },
        "expectedEvidence": [
          "인덱스 추가만으로 해소하기 어려운 병목을 근거로 조인 정리의 필요성을 설명함",
          "실행 계획에서 확인한 조회 구조를 적용한 개선 조치와 연결함",
          "개선 전후의 조회 시간을 실제 측정값으로 제시함"
        ]
      },
      "question": "포켓마켓에서 인덱스 추가와 조인 정리로 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요. 인덱스 추가만으로는 부족한 이유는 무엇인가요?",
      "answerTip": "당시 실제로 확인한 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "실행 계획에서 확인한 병목을 들어 인덱스 추가 외에 조인 정리가 필요한 이유를 구체적으로 설명한다.",
            "적용한 개선 조치를 조회 구조와 연결하고, 전후 응답 시간을 측정값으로 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조인 정리가 필요한 이유는 설명하지만 실제 조회 구조와의 연결이나 전후 측정 근거는 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "조인 정리가 필요한 이유를 설명하지 못하거나 인덱스 추가와 시간 단축 사실만 반복한다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 파악한 장애 원인을 바탕으로 코드 수정과 배포 점검의 역할을 구분한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 인턴 때 배포 다음 날 같은 알림이 두 번 발송된다는 문의가 들어왔다.",
          "task": "중복 발송의 원인을 해결하고 이후 배포에서도 같은 장애를 막아야 했다.",
          "action": "로그로 두 서버의 스케줄러 동시 실행을 찾아 잠금을 적용하고 배포 점검 항목을 추가했다.",
          "result": "중복 실행을 수정하고 같은 원인을 배포 때 다시 확인할 수 있는 점검 항목을 남겼다."
        },
        "expectedEvidence": [
          "잠금 수정 외에 배포 점검이 필요한 재발 위험을 구체적으로 설명함",
          "두 서버의 동시 실행을 드러낸 로그를 배포 점검의 필요성과 연결함",
          "잠금 수정의 복구 역할과 체크리스트의 재발 방지 역할을 구분함"
        ]
      },
      "question": "포켓마켓에서 잠금으로 고친 스케줄러를 배포 체크리스트에도 넣으셨던데요. 잠금 수정 외에 배포 점검도 필요하다고 보신 근거는 무엇이었나요?",
      "answerTip": "당시 판단을 떠올릴 수 있는 구체적인 내용으로 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "로그에서 확인한 두 서버의 동시 실행을 근거로 배포 점검이 필요한 재발 위험을 구체적으로 설명한다.",
            "잠금으로 기존 오류를 고치는 역할과 체크리스트로 재발을 막는 역할을 구분해 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "배포 점검이 필요한 이유는 답하지만 로그에서 확인한 원인과의 연결이나 복구와 예방의 구분은 일반적이다."
          ]
        },
        "poor": {
          "criteria": [
            "배포 점검을 추가한 근거를 설명하지 못하거나 잠금 적용과 체크리스트 추가 사실만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "인터뷰에서 파악한 요구를 개발 가능한 범위로 구체화하면서 핵심 목적을 유지했는지 판단하는 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 다섯 곳을 인터뷰한 서비스 기획 과제에서 개발 담당 팀원과 범위를 조정했다.",
          "task": "세탁소의 핵심 요구를 충족할 수 있는 구현 범위를 요구사항으로 구체화해야 했다.",
          "action": "인터뷰에서 확인한 목적에 비추어 조정한 범위가 충족하는 요구를 설명한다.",
          "result": "조정한 구현 범위가 핵심 요구를 충족한다는 근거가 요구사항 문서에서 확인된다."
        },
        "expectedEvidence": [
          "조정한 범위로 충족할 수 있는 핵심 요구를 인터뷰 내용에 근거해 설명한다.",
          "실제 요구사항에 정리한 구현 범위를 들어 요구 충족의 근거를 뒷받침한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 다섯 곳의 인터뷰를 바탕으로 개발 담당 팀원과 범위를 조정하셨던데요. 조정한 범위로 세탁소의 요구를 충족할 수 있다고 보는 근거는 무엇인가요?",
      "answerTip": "당시 경험에서 구체적인 사례 하나를 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인터뷰에서 확인한 핵심 요구와 조정한 구현 범위를 연결해 요구를 충족할 수 있는 근거를 설명한다.",
            "요구사항 문서에 구체화한 실제 범위를 사례로 들어 설명을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "조정한 범위가 요구를 충족하는 이유는 답하지만 인터뷰 내용이나 실제 요구사항과의 연결이 모호하다."
          ]
        },
        "poor": {
          "criteria": [
            "범위를 조정했다는 사실만 반복하거나 세탁소의 요구를 충족할 수 있는 근거를 설명하지 못한다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 담은 화면설계서가 개발자의 추가 해석 없이 구현 가능한 수준인지 확인한 방법을 파악한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "세탁소 예약 서비스 과제에서 예외 상황을 포함한 화면설계서 28장을 작성했다.",
          "task": "개발 담당 팀원이 예외 상황의 처리 방식을 명확히 이해할 수 있도록 설계해야 했다.",
          "action": "구체적인 예외 상황을 들어 화면설계서의 설명이 충분한지 확인한 방법을 설명한다.",
          "result": "예외 상황의 화면 동작을 추가 추측 없이 구현할 수 있는지 확인한 내용이 드러난다."
        },
        "expectedEvidence": [
          "개발자가 예외 처리를 되묻지 않아도 되는지 확인한 실제 방법을 설명한다.",
          "특정 예외 상황의 화면 설명에서 확인된 명확한 부분이나 모호한 부분을 제시한다."
        ]
      },
      "question": "세탁소 예약 서비스 과제에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요. 개발 담당 팀원이 예외 처리를 되묻지 않아도 될 수준인지는 무엇으로 확인하셨나요?",
      "answerTip": "실제로 확인했던 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "화면설계서만으로 예외 처리 방식을 이해할 수 있는지 확인한 실제 방법을 구체적으로 설명한다.",
            "특정 예외 상황에서 설명이 명확했거나 모호했던 부분을 들어 확인 내용을 뒷받침한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "설명의 충분함을 확인한 방법은 답하지만 구체적인 예외 상황이나 확인 내용은 제시하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "예외 상황을 작성했다는 사실만 반복하거나 구현에 충분한 설명인지 확인한 방법을 답하지 못한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "평소와 다른 진통제 용량을 처방대로 수행하기 전에 멈추고 확인해야 하는 판단 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원 근무 때 수술 후 환자에게 평소 두 배 용량의 진통제가 처방되었다.",
          "task": "변경된 용량을 그대로 투약해도 되는지 확인되지 않은 상태에서 수행 여부를 판단해야 했다.",
          "action": "용량의 안전성을 단정하지 않고 투약을 보류한 뒤 담당의에게 확인했다.",
          "result": "담당의 확인으로 처방 입력 오류를 발견해 잘못된 용량의 투약을 막았다."
        },
        "expectedEvidence": [
          "처방을 그대로 수행하기보다 확인을 우선한 근거를 설명한다.",
          "평소와 다른 용량의 안전성을 확인 전에 단정할 수 없었던 이유를 제시한다.",
          "담당의 확인으로 입력 오류를 발견한 결과를 근거와 연결한다."
        ]
      },
      "question": "푸른결종합병원에서 평소 두 배 용량의 진통제 처방에 투약을 멈추셨던데요. 처방대로 투약하는 것보다 담당의 확인이 먼저라고 판단한 이유는 무엇이었나요?",
      "answerTip": "당시의 판단을 중심으로 구체적으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "두 배 용량의 안전성을 확인하지 못한 상황과 연결해 투약보다 담당의 확인을 우선한 근거를 설명한다.",
            "평소와 다르면 무조건 오류라고 단정하지 않고, 확인을 통해 입력 오류를 발견한 결과를 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "용량이 달라 투약을 보류했다고 답하지만, 확인이 필요했던 이유는 환자 안전이라는 일반론에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "투약보다 확인을 우선한 근거를 설명하지 못하거나, 의심스러운 처방도 그대로 수행해야 한다고 답한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "교대 시간대의 낙상 기록을 근거로 다음 근무자에게 전달할 환자 정보를 정한 판단을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "푸른결종합병원에서 수술 후 첫 보행 환자의 낙상이 교대 시간대에 몰린 점을 확인했다.",
          "task": "환자의 보행 관련 상태가 교대 후에도 이어지도록 인수인계 정보를 구체화해야 했다.",
          "action": "보행 보조 여부가 다음 근무자의 환자 관찰에 필요한 이유를 판단해 체크리스트에 추가했다.",
          "result": "다음 근무자가 환자의 보행 보조 필요를 놓치지 않도록 정보가 전달된다."
        },
        "expectedEvidence": [
          "보행 보조 여부를 다음 근무자에게 꼭 전달해야 하는 이유를 설명한다.",
          "교대 시간대 낙상 기록과 보행 보조 정보의 전달 필요성을 연결한다.",
          "해당 정보가 다음 근무자의 환자 관찰에 어떤 차이를 만드는지 설명한다."
        ]
      },
      "question": "푸른결종합병원에서 교대 시간대 낙상 기록을 보고 인수인계에 보행 보조 여부를 추가하셨던데요. 그 정보를 다음 근무자에게 꼭 넘겨야 한다고 보신 이유는 무엇이었나요?",
      "answerTip": "본인이 판단했던 내용을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "교대 시간대 낙상 기록을 근거로 보행 보조 여부를 다음 근무자에게 전달해야 하는 이유를 구체적으로 설명한다.",
            "정보 전달이 다음 근무자의 환자 관찰과 보행 보조 필요 판단에 만드는 차이를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "보행 보조 여부를 전달해야 한다고 답하지만, 이유는 낙상 예방이나 인수인계의 중요성에 대한 일반론에 머문다."
          ]
        },
        "poor": {
          "criteria": [
            "보행 보조 여부를 전달해야 하는 이유를 설명하지 못하거나, 체크리스트 개선 성과만 반복한다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P04",
  "interviews": [
    {
      "categoryId": "P04-C1",
      "itemId": "P04-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "주어진 하중에서 계산한 축 지름의 타당성을 하중 전달 경로와 허용 가능한 응력에 근거해 설명하는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
